const entrada = $('Webhook Prometheus').first().json;
const payload = entrada.body ?? entrada;

const issuesResp = $('Obtener Incidencias MantisBT').first().json;
const openIssues = (issuesResp.issues || []).filter(i => {
  const st = (i.status?.name || '').toLowerCase();
  return st !== 'resolved' && st !== 'closed';
});

const promMetrics = $('Consultar Métricas Prometheus').first().json?.data?.result || [];
const liveTargetsDown = promMetrics.filter(m => m.value?.[1] !== '1').map(m => `${m.metric?.job || 'unknown'} (${m.metric?.instance || 'unknown'})`);
const liveTargetsUp = promMetrics.filter(m => m.value?.[1] === '1').map(m => `${m.metric?.job || 'unknown'} (${m.metric?.instance || 'unknown'})`);

const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];
const results = [];

for (const alerta of alerts) {
  const status = String(alerta.status ?? payload.status ?? 'firing').toLowerCase();
  const labels = alerta.labels ?? {};
  const annotations = alerta.annotations ?? {};

  const alertname = String(labels.alertname ?? 'Alerta de Infraestructura');
  const instance = String(labels.instance ?? 'No especificada');
  const job = String(labels.job ?? 'infraestructura');
  const severity = String(labels.severity ?? 'warning').toLowerCase();
  const summary = String(annotations.summary ?? alertname).trim();
  const detalle = String(annotations.description ?? 'Sin descripción adicional').trim();
  const startsAt = alerta.startsAt ?? new Date().toISOString();

  // Buscar coincidencia en tickets abiertos (por alertname o por instancia/servicio)
  const existingIssue = openIssues.find(iss => {
    const s = (iss.summary || '').toLowerCase();
    const d = (iss.description || '').toLowerCase();
    const targetName = alertname.toLowerCase();
    const targetInst = instance.toLowerCase();
    const targetJob = job.toLowerCase();
    const matchesName = s.includes(targetName) || d.includes(targetName) || s.includes(targetJob) || d.includes(targetJob);
    const matchesInst = targetInst === 'no especificada' || s.includes(targetInst) || d.includes(targetInst);
    return matchesName && matchesInst;
  });

  const mantisPriority = severity === 'critical' ? 'urgent' : severity === 'warning' ? 'high' : 'normal';
  const mantisSeverity = severity === 'critical' ? 'major' : severity === 'warning' ? 'minor' : 'trivial';

  // Matriz de asignación según componente
  let responsible = 'Equipo DevOps';
  if (job.includes('postgres') || alertname.toLowerCase().includes('postgres')) {
    responsible = 'Méndez / Orellana (DBA & Clustering)';
  } else if (job.includes('cadvisor') || alertname.toLowerCase().includes('container')) {
    responsible = 'Guari (Contenedores & Recursos)';
  } else if (job.includes('grafana') || job.includes('prometheus')) {
    responsible = 'Figueroa (Observabilidad)';
  }

  const grafanaUrl = 'http://localhost:3000/d/observabilidad-integral/observabilidad-integral?from=now-1h&to=now';

  if (status === 'resolved') {
    if (existingIssue) {
      results.push({
        action: 'RESOLVE',
        issueId: existingIssue.id,
        alertname,
        instance,
        severity,
        status: 'RESOLVED',
        summary: `[RESUELTO] ${summary}`,
        resolutionNote: `[AUTO-RECUPERACIÓN] Prometheus reporta que la alerta '${alertname}' en '${instance}' fue resuelta a las ${new Date().toISOString()}. El servicio se ha restablecido exitosamente.`,
        responsible,
        grafanaUrl,
        mantisUrl: `http://localhost:8989/view.php?id=${existingIssue.id}`,
        details: `Incidencia #${existingIssue.id} auto-resuelta por normalización de métricas en Prometheus.`
      });
    }
  } else {
    // Alerta FIRING
    if (existingIssue) {
      // Deduplicación / Flapping: ya existe un ticket abierto
      results.push({
        action: 'NOTE',
        issueId: existingIssue.id,
        alertname,
        instance,
        severity,
        status: 'DEDUP_NOTE',
        summary: `[REINCIDENCIA] ${summary}`,
        followupNote: `[SEGUIMIENTO AUTOMÁTICO] La alerta '${alertname}' continúa activa (FIRING) en '${instance}'.\nRegistro: ${new Date().toISOString()}\nTelemetría en vivo: ${liveTargetsDown.length} targets caídos, ${liveTargetsUp.length} targets UP.`,
        responsible,
        grafanaUrl,
        mantisUrl: `http://localhost:8989/view.php?id=${existingIssue.id}`,
        details: `Alerta reincidente agregada como nota de seguimiento en ticket #${existingIssue.id}.`
      });
    } else {
      // Alerta Nueva: crear ticket
      const fullDescription = [
        '====================================================',
        ' ALERTA AUTOMÁTICA DE INFRAESTRUCTURA (ENRIQUECIDA)',
        '====================================================',
        `Alerta          : ${alertname}`,
        `Estado          : FIRING`,
        `Severidad       : ${severity.toUpperCase()}`,
        `Componente/Job  : ${job}`,
        `Instancia       : ${instance}`,
        `Detalle         : ${detalle}`,
        `Inicio          : ${startsAt}`,
        `Responsable     : ${responsible}`,
        '----------------------------------------------------',
        ' TELEMETRÍA EN VIVO AL MOMENTO DEL DISPARO',
        '----------------------------------------------------',
        `Servicios UP    : ${liveTargetsUp.length}`,
        `Servicios DOWN  : ${liveTargetsDown.length > 0 ? liveTargetsDown.join(', ') : 'Ninguno adicional'}`,
        '----------------------------------------------------',
        `Dashboard       : ${grafanaUrl}`,
        'Origen          : Prometheus / Alertmanager / n8n'
      ].join('\n');

      results.push({
        action: 'CREATE',
        alertname,
        instance,
        severity,
        status: 'CREATED',
        summary: `[${severity.toUpperCase()}] ${summary}`.slice(0, 128),
        description: fullDescription,
        mantisPriority,
        mantisSeverity,
        responsible,
        grafanaUrl,
        liveTargetsDownCount: liveTargetsDown.length,
        liveTargetsUpCount: liveTargetsUp.length,
        details: `Nueva incidencia generada y asignada preventivamente a ${responsible}.`
      });
    }
  }
}

return results.map(r => ({ json: r }));

